
.form-card {
  width: 100%;
  max-width: 560px;
  background: var(--c-surface);
  border: 2px solid var(--c-border);
  border-radius: 12px;
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  color: var(--c-text);
  font-size: 13px;
  line-height: 1.5;
  margin: 12px auto;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.35);
}

.form-header {
  text-align: center;
  margin-bottom: 4px;

  h2 {
    font-size: 18px;
    font-weight: 700;
    color: var(--c-primary);
    margin: 0 0 4px 0;
  }

  .subtitle {
    color: var(--c-text-muted);
    font-size: 12px;
    margin: 0;
  }
}

.form-section {
  background: var(--c-surface-light);
  border-radius: 8px;
  padding: 12px 14px;

  h3 {
    font-size: 14px;
    font-weight: 600;
    color: var(--c-accent);
    margin: 0 0 10px 0;
    display: flex;
    align-items: center;
    gap: 6px;
  }
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.field-full {
  grid-column: 1 / -1;
}

label {
  font-size: 12px;
  color: var(--c-text-muted);
}

input, select, textarea {
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  padding: 6px 10px;
  color: var(--c-text);
  font-size: 13px;
  font-family: var(--font-main);
  outline: none;
  transition: border-color 0.2s;

  &:focus {
    border-color: var(--c-primary);
  }

  &::placeholder {
    color: var(--c-text-muted);
    opacity: 0.6;
  }
}

textarea {
  resize: vertical;
  min-height: 36px;
}

.form-actions {
  display: flex;
  justify-content: center;
  margin-top: 4px;
}

.btn-submit {
  background: var(--c-primary);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 10px 28px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: all 0.2s;
  font-family: var(--font-main);

  &:hover:not(:disabled) {
    background: #5a4bd5;
    transform: translateY(-1px);
  }

  &:active:not(:disabled) {
    transform: translateY(0);
  }

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
}

.success-msg {
  text-align: center;
  color: var(--c-success);
  font-size: 13px;
  padding: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

@media (max-width: 500px) {
  .form-grid {
    grid-template-columns: 1fr;
  }
}
